29	func (i *importGraph) addNode(name string) {
30		if i.nodes == nil {
31			i.nodes = make(map[string]struct{})
32		}
33		if _, exists := i.nodes[name]; exists {
34			return
35		}
36		i.nodes[name] = struct{}{}
