// <dir>/Caddyfile, so relative imports resolve inside dir.
func parseInDir(t *testing.T, dir, body string) ([]ServerBlock, error) {
	t.Helper()
	root := filepath.Join(dir, "Caddyfile")
	return Parse(root, []byte(body))
